"""Intent tests for the snake world: TC-06, TC-10 (snake half) and TC-12 (snake).

The tests keep their own model of the board (read from `draw()` at the start, then advanced by
the rules in spec.md) and check every step of the real world against it. Which action index is
which relative turn is not part of the contract, so the mapping is read off the world once and
then held to for every later step and seed.
"""

import json
from collections import deque
from collections.abc import Callable
from dataclasses import dataclass
from pathlib import Path
from typing import Any

import numpy as np
import pytest

from rllab.core import ActionError, Discrete, Step
from rllab.worlds.snake import Snake

FIXTURES = Path(__file__).resolve().parents[2] / "fixtures" / "rllab"
GRID = 10
HUNGER = 100
Cell = tuple[int, int]


def load(case: str, name: str) -> Any:
    return json.loads((FIXTURES / case / f"{name}.json").read_text())


TC06 = load("TC-06", "input")
TC06_EXPECTED = load("TC-06", "expected")
TC10 = load("TC-10", "input")
TC10_EXPECTED = load("TC-10", "expected")
TC12 = load("TC-12", "input")
SEEDS: list[int] = TC06["seeds"]
TABLE: dict[str, Cell] = {k: (v[0], v[1]) for k, v in TC06_EXPECTED["turns_from_up"].items()}
START_LENGTH: int = TC06_EXPECTED["start_length"]


# ----------------------------------------------------------------------------- board model


def add(a: Cell, b: Cell) -> Cell:
    return (a[0] + b[0], a[1] + b[1])


def sub(a: Cell, b: Cell) -> Cell:
    return (a[0] - b[0], a[1] - b[1])


def quarter(v: Cell) -> Cell:
    """A quarter turn that takes the table's `straight` (up) to its `right`."""
    up, right = TABLE["straight"], TABLE["right"]
    turned = (-v[1], v[0])
    return turned if (-up[1], up[0]) == right else (v[1], -v[0])


def turns(heading: Cell) -> dict[str, Cell]:
    """The relative-turn table rotated from heading up to `heading`."""
    table = dict(TABLE)
    for _ in range(4):
        if table["straight"] == heading:
            return table
        table = {k: quarter(v) for k, v in table.items()}
    raise AssertionError(f"heading {heading} is not one grid cell")


def inside(c: Cell) -> bool:
    return 0 <= c[0] < GRID and 0 <= c[1] < GRID


def cell(obj: Any) -> Cell:
    assert obj.size == pytest.approx(1.0)
    x, y = round(obj.x), round(obj.y)
    assert (x, y) == (obj.x, obj.y)
    return (x, y)


def board(world: Any) -> tuple[Cell, list[Cell], list[Cell]]:
    """Head, body cells and food cells as `draw()` shows them."""
    state = world.draw()
    assert (state.width, state.height) == (GRID, GRID)
    snake = [o for o in state.objects if o.agent == 0]
    heads = [o for o in snake if "head" in o.kind]
    assert len(heads) == 1
    body = [cell(o) for o in snake if o is not heads[0]]
    food = [cell(o) for o in state.objects if o.agent is None]
    return cell(heads[0]), body, food


@dataclass
class Model:
    cells: list[Cell]  # head first
    food: Cell
    hungry: int = 0
    eaten: int = 0
    steps: int = 0

    @property
    def heading(self) -> Cell:
        return sub(self.cells[0], self.cells[1])

    def moves(self) -> dict[str, Cell]:
        return {k: add(self.cells[0], d) for k, d in turns(self.heading).items()}


def start(world: Any) -> Model:
    """Read the start board; check SNAKE-01 on it."""
    head, body, food = board(world)
    assert len(body) + 1 == START_LENGTH
    assert len(food) == 1
    cells = [head]
    rest = list(body)
    while rest:
        nxt = [c for c in rest if sum(map(abs, sub(c, cells[-1]))) == 1]
        assert len(nxt) == 1, "the start snake is one straight-ish chain"
        cells.append(nxt[0])
        rest.remove(nxt[0])
    assert all(2 <= x <= GRID - 3 and 2 <= y <= GRID - 3 for x, y in cells), "near the centre"
    assert inside(food[0])
    assert food[0] not in cells
    return Model(cells, food[0])


def act(world: Any, action: int) -> Step:
    return world.step(np.asarray([action]))


def mapping() -> dict[str, int]:
    """Which action index is left, right and straight, read from the seed-0 start."""
    found: dict[str, int] = {}
    for action in range(3):
        world = Snake()
        world.reset(SEEDS[0])
        model = start(world)
        act(world, action)
        head, _, _ = board(world)
        labels = [k for k, c in model.moves().items() if c == head]
        assert len(labels) == 1, f"action {action} moved the head off the turn table"
        found[labels[0]] = action
    assert set(found) == set(TABLE)
    return found


def advance(world: Any, model: Model, label: str, actions: dict[str, int]) -> tuple[Step, str]:
    """Step the world and the model; check they agree. Returns the step and why it ended."""
    new = model.moves()[label]
    tail = model.cells[-1]
    step = act(world, actions[label])
    model.steps += 1
    if not inside(new):
        assert step.done, f"head left the grid at {new} but the episode went on"
        return step, "wall"
    if new in model.cells[:-1]:
        assert step.done, f"head hit the body at {new} but the episode went on"
        return step, "body"
    if new == tail and step.done:
        return step, "body"  # moving into the tail's cell: either rule is allowed
    eats = new == model.food
    model.cells = [new, *model.cells] if eats else [new, *model.cells[:-1]]
    model.eaten += eats
    model.hungry = 0 if eats else model.hungry + 1
    hungry, out_of_time = model.hungry >= HUNGER, model.steps >= world.spec.max_steps
    assert step.done == (hungry or out_of_time), (model.steps, model.hungry)
    assert step.truncated == (out_of_time and not hungry)
    if step.done:
        return step, "hunger" if hungry else "max_steps"
    head, body, food = board(world)
    assert head == new
    assert sorted([head, *body]) == sorted(model.cells)
    assert len(food) == 1
    assert inside(food[0])
    assert food[0] not in model.cells, "food is on a free cell"
    if not eats:
        assert food[0] == model.food, "food moves only when eaten"
    model.food = food[0]
    return step, ""


# ------------------------------------------------------------------------------- policies

Policy = Callable[[Model, np.random.Generator], str]


def wander(model: Model, rng: np.random.Generator) -> str:
    return str(rng.choice(sorted(TABLE)))


def safe(model: Model, rng: np.random.Generator) -> str:
    """A move that neither dies nor eats, when there is one."""
    moves = model.moves()
    ok = [k for k in sorted(moves) if inside(moves[k]) and moves[k] not in model.cells]
    hungry = [k for k in ok if moves[k] != model.food]
    return str(rng.choice(hungry or ok or sorted(moves)))


def seek(model: Model, rng: np.random.Generator) -> str:
    """The first move of a shortest path to the food around the body."""
    moves = model.moves()
    first = {c: k for k, c in moves.items() if inside(c) and c not in model.cells}
    queue = deque((c, k) for c, k in first.items())
    seen = set(first) | set(model.cells)
    while queue:
        here, label = queue.popleft()
        if here == model.food:
            return label
        for d in TABLE.values():
            for n in (add(here, d), sub(here, d)):
                if inside(n) and n not in seen:
                    seen.add(n)
                    queue.append((n, label))
    return safe(model, rng)


def play(seed: int, policy: Policy, actions: dict[str, int]) -> tuple[Any, Model, str]:
    world = Snake()
    world.reset(seed)
    model = start(world)
    rng = np.random.default_rng(seed)
    for _ in range(world.spec.max_steps):
        step, why = advance(world, model, policy(model, rng), actions)
        if step.done:
            return world, model, why
    raise AssertionError("the episode outlived max_steps")


def eat_then(target: int, after: Policy) -> Policy:
    def policy(model: Model, rng: np.random.Generator) -> str:
        return seek(model, rng) if model.eaten < target else after(model, rng)

    return policy


def spin(model: Model, rng: np.random.Generator) -> str:
    return "left"


def score_of(world: Any) -> float:
    (team,) = world.spec.teams
    return float(world.result().scores[team.name])


def same_step(a: Step, b: Step) -> bool:
    return (
        np.array_equal(a.obs, b.obs)
        and np.array_equal(a.rewards, b.rewards)
        and np.array_equal(a.active, b.active)
        and (a.done, a.truncated) == (b.done, b.truncated)
    )


# ------------------------------------------------------------------------------------ TC-06


@pytest.mark.intent
def test_spec_offers_three_discrete_actions() -> None:
    spec = Snake().spec
    assert spec.world == TC06["world"]
    assert spec.variant == TC06["variant"]
    assert isinstance(spec.action, Discrete)
    assert spec.action.n == len(TABLE)


@pytest.mark.intent
@pytest.mark.parametrize("seed", SEEDS)
def test_start_is_three_cells_near_the_centre_with_food_on_a_free_cell(seed: int) -> None:
    world = Snake()
    world.reset(seed)
    model = start(world)
    assert len(model.cells) == START_LENGTH


@pytest.mark.intent
def test_turning_left_while_heading_up_moves_the_head_one_cell_left() -> None:
    actions = mapping()
    for seed in SEEDS:
        world = Snake()
        world.reset(seed)
        model = start(world)
        if model.heading == TABLE["straight"]:
            head = model.cells[0]
            act(world, actions["left"])
            assert sub(board(world)[0], head) == TABLE["left"]
            return
    raise AssertionError("no seed in TC-06 starts heading up")


@pytest.mark.intent
@pytest.mark.parametrize("seed", SEEDS)
def test_random_rollout_follows_the_rules_and_scores_food_eaten(seed: int) -> None:
    world, model, why = play(seed, wander, mapping())
    assert why in {"wall", "body", "hunger"}
    assert score_of(world) == model.eaten == len(model.cells) - START_LENGTH
    assert world.result().length == model.steps


@pytest.mark.intent
def test_episode_ends_exactly_after_100_steps_without_food() -> None:
    actions = mapping()
    for seed in SEEDS[:5]:
        world, model, why = play(seed, safe, actions)
        assert why == "hunger"
        assert model.hungry == HUNGER
        assert score_of(world) == model.eaten


@pytest.mark.intent
def test_head_moving_into_the_body_ends_the_episode() -> None:
    actions = mapping()
    causes = [play(seed, eat_then(3, spin), actions)[2] for seed in SEEDS]
    assert "body" in causes


@pytest.mark.intent
def test_twelve_food_eaten_scores_twelve() -> None:
    instance = TC06_EXPECTED["spec_instance"]
    actions = mapping()
    for seed in SEEDS:
        world, model, _ = play(seed, eat_then(instance["food_eaten"], safe), actions)
        if model.eaten == instance["food_eaten"]:
            assert score_of(world) == instance["score"]
            assert len(model.cells) - START_LENGTH == instance["score"]
            return
    raise AssertionError("no seed reached the TC-06 food count")


# ------------------------------------------------------------------------------------ TC-10


@pytest.mark.intent
def test_out_of_range_action_is_refused_and_leaves_the_world_unchanged() -> None:
    (case,) = [c for c in TC10["actions"] if c["world"] == "snake"]
    (expected,) = [e for e in TC10_EXPECTED["errors"] if e["agent"] == "snake"]
    world = Snake()
    first = world.reset(case["seed"])
    before = world.draw()
    with pytest.raises(ActionError, match=expected["agent"]) as caught:
        world.step(np.asarray(case["action"]))
    assert isinstance(caught.value, ValueError)
    assert caught.value.agent == expected["agent"]
    assert caught.value.value == expected["value"]
    assert world.draw() == before

    fresh = Snake()
    assert same_step(fresh.reset(case["seed"]), first)
    assert same_step(act(world, 0), act(fresh, 0))
    assert world.draw() == fresh.draw()


@pytest.mark.intent
def test_step_after_done_raises_runtime_error() -> None:
    world, _, _ = play(SEEDS[0], wander, mapping())
    with pytest.raises(RuntimeError):
        act(world, 0)


# ------------------------------------------------------------------------------------ TC-12


@pytest.mark.intent
@pytest.mark.repro
def test_same_seed_gives_the_same_start() -> None:
    seed = TC12["seed"]
    one, two = Snake(), Snake()
    first = one.reset(seed)
    assert same_step(one.reset(seed), first)
    assert same_step(two.reset(seed), first)
    assert one.draw() == two.draw()


@pytest.mark.intent
@pytest.mark.repro
def test_same_seed_and_actions_give_the_same_steps() -> None:
    seed = TC12["seed"]
    one, two = Snake(), Snake()
    one.reset(seed)
    two.reset(seed)
    rng = np.random.default_rng(seed)
    for action in rng.integers(0, 3, size=TC12["steps"]):
        a, b = act(one, int(action)), act(two, int(action))
        assert same_step(a, b)
        assert one.draw() == two.draw()
        if a.done:
            break


@pytest.mark.intent
def test_observations_keep_their_shape_and_every_agent_is_drawn_and_teamed() -> None:
    (case,) = [w for w in TC12["worlds"] if w[0] == "snake"]
    world = Snake()
    spec = world.spec
    assert (spec.world, spec.variant) == tuple(case)
    n = len(spec.agents)
    for i in range(n):
        assert sum(i in team.agents for team in spec.teams) == 1
    rng = np.random.default_rng(TC12["seed"])
    step, episode = world.reset(TC12["seed"]), 0
    for _ in range(TC12["steps"]):
        assert step.obs.shape == (n, spec.obs_len)
        assert step.obs.dtype == np.float32
        assert step.rewards.shape == (n,)
        assert step.rewards.dtype == np.float32
        assert step.active.shape == (n,)
        assert step.active.dtype == np.bool_
        drawn = {o.agent for o in world.draw().objects}
        assert set(range(n)) <= drawn
        if step.done:
            episode += 1
            step = world.reset(TC12["seed"] + episode)
        else:
            step = act(world, int(rng.integers(0, 3)))
